 */
function Rnode_graph_get_pin_at(int $graph, float $x, float $y): int {}

/**
 * The link under a point of the widget, or 0 (hidden links are never under it).
 */
function Rnode_graph_get_link_at(int $graph, float $x, float $y): int {}

/**
